package glitch

import data.glitch_lib

# Weak cryptographic algorithms and patterns
weak_algorithms := {"DES", "3DES", "TRIPLEDES", "RC2", "RC4", "BLOWFISH", "MD5", "SHA1", "SHA-1"}

# Weak TLS/SSL versions
weak_tls_versions := {"TLSV1.0", "TLSV1.1", "SSLV3", "SSLV2", "TLS1.0", "TLS1.1", "SSL3", "SSL2", "TLSV1", "TLSV2", "SSL23"}

# Weak cipher modes
weak_modes := {"ECB"}

# Weak cipher suite patterns (detectable substrings)
weak_cipher_patterns := {"_RC4_", "_3DES_", "_DES_", "_EXPORT_", "_NULL_", "_anon_", "_CBC_"}

# Unencrypted/weak protocols
weak_protocols := {"PLAINTEXT", "HTTP", "FTP", "TELNET"}

# Extended attribute names that may contain weak crypto
crypto_attr_names := {
    "algorithm", "encryption_algorithm", "cipher", "crypto", "kms_key_spec", 
    "key_spec", "key_algorithm", "tls_version", "ssl_policy", "min_tls_version",
    "security_policy", "policy_name", "cipher_suite", "cipher_suites", "sse_algorithm",
    "server_side_encryption", "encrypt", "encryption", "hash", "checksum",
    "digest", "signature_algorithm", "token_signing_algorithm"
}

# Key size attribute names
key_size_attrs := {"key_length", "key_size", "bits", "rsa_key_size", "key_length_in_bits"}

# Mode attribute names
mode_attrs := {"mode", "block_mode", "encryption_mode", "cipher_mode"}

# Encryption enabled attribute names
encryption_enabled_attrs := {
    "storage_encrypted", "encryption_at_rest", "encrypted", 
    "in_transit_encryption", "encryption_in_transit", "transit_encryption_enabled"
}

# Helper: check if string value contains weak algorithm
string_contains_weak_algo(val) {
    upper_val := upper(val)
    weak_algorithms[upper_val]
} else {
    upper_val := upper(val)
    weak_algorithms[upper_trim]
    startswith(upper_val, upper_trim)
} else {
    upper_val := upper(val)
    weak_algorithms[upper_trim]
    contains(upper_val, upper_trim)
} else {
    contains(lower(val), "md5")
} else {
    contains(lower(val), "sha1")
} else {
    contains(lower(val), "sha-1")
}

# Helper: check if string value contains weak cipher suite pattern
string_contains_weak_cipher(val) {
    pattern := weak_cipher_patterns[_]
    contains(upper(val), pattern)
}

# Helper: check if string value is weak TLS version
is_weak_tls_string(val) {
    upper_val := upper(val)
    weak_tls_versions[upper_val]
} else {
    upper_val := upper(val)
    startswith(upper_val, "TLS1.0")
} else {
    upper_val := upper(val)
    startswith(upper_val, "TLS1.1")
} else {
    upper_val := upper(val)
    startswith(upper_val, "SSL")
    not startswith(upper_val, "SSL_")
}

# Check any node for weak algorithm string recursively
node_contains_weak_algo(node) {
    node.ir_type == "String"
    string_contains_weak_algo(node.value)
} else {
    node.ir_type == "FunctionCall"
    arg := node.args[_]
    node_contains_weak_algo(arg)
} else {
    node.ir_type == "Array"
    elem := node.value[_]
    node_contains_weak_algo(elem)
} else {
    node.ir_type == "Hash"
    pair := node.value[_]
    node_contains_weak_algo(pair.value)
} else {
    node.ir_type == "MethodCall"
    node_contains_weak_algo(node.receiver)
} else {
    node.ir_type == "Access"
    node_contains_weak_algo(node.left)
} else {
    node.ir_type == "UnaryOperation"
    node_contains_weak_algo(node.expr)
} else {
    node.ir_type == "BinaryOperation"
    node_contains_weak_algo(node.left)
} else {
    node.ir_type == "BinaryOperation"
    node_contains_weak_algo(node.right)
}

# Check any node for weak cipher suite string recursively
node_contains_weak_cipher(node) {
    node.ir_type == "String"
    string_contains_weak_cipher(node.value)
} else {
    node.ir_type == "Array"
    elem := node.value[_]
    node_contains_weak_cipher(elem)
} else {
    node.ir_type == "Hash"
    pair := node.value[_]
    node_contains_weak_cipher(pair.value)
}

# Check any node for weak TLS version recursively
node_contains_weak_tls(node) {
    node.ir_type == "String"
    is_weak_tls_string(node.value)
}

# Check for weak mode
node_contains_weak_mode(node) {
    node.ir_type == "String"
    weak_modes[upper(node.value)]
}

# Check if encryption is explicitly disabled
is_encryption_disabled(node) {
    node.ir_type == "Boolean"
    node.value == false
}

# Check key size against algorithm
is_weak_key_size(key_size_node, algo_node) {
    key_size_node.ir_type == "Integer"
    key_size_node.value < 128
} else {
    key_size_node.ir_type == "Integer"
    key_size_node.value < 2048
    algo_node.ir_type == "String"
    contains(lower(algo_node.value), "rsa")
} else {
    key_size_node.ir_type == "Integer"
    key_size_node.value < 256
    algo_node.ir_type == "String"
    contains(lower(algo_node.value), "ec")
}

# Check if attribute name suggests crypto content
is_crypto_attr_name(name) {
    lower_name := lower(name)
    cn := crypto_attr_names[_]
    contains(lower_name, cn)
}

# Check if attribute name suggests encryption enabled
is_encryption_attr_name(name) {
    en := encryption_enabled_attrs[_]
    name == en
}

# Check if attribute name suggests mode
is_mode_attr_name(name) {
    mn := mode_attrs[_]
    contains(lower(name), mn)
}

# Check if attribute name suggests key size
is_key_size_attr_name(name) {
    kn := key_size_attrs[_]
    contains(lower(name), kn)
}

# Recursively walk through all nested structures to find values
walk_node_for_crypto(node, found) {
    node.ir_type == "String"
    string_contains_weak_algo(node.value)
    found := node
} else {
    node.ir_type == "Array"
    elem := node.value[_]
    walk_node_for_crypto(elem, found)
} else {
    node.ir_type == "Hash"
    pair := node.value[_]
    walk_node_for_crypto(pair.value, found)
} else {
    node.ir_type == "FunctionCall"
    arg := node.args[_]
    walk_node_for_crypto(arg, found)
}

# Generic detection: FunctionCall with weak algorithm in name or args
Glitch_Analysis[result] {
    parent := glitch_lib._gather_parent_unit_blocks[_]
    parent.path != ""

    # Walk entire parent structure to find any FunctionCall
    walk(parent, [_, node])
    node.ir_type == "FunctionCall"

    # Check function name for crypto patterns
    contains(lower(node.name), "hash")
    arg := node.args[_]
    arg.ir_type == "String"
    weak_algorithms[upper(arg.value)]

    result := {
        "type": "sec_weak_crypt",
        "element": node,
        "path": parent.path,
        "description": "Use of weak cryptographic hash algorithm in function call - Weak or deprecated cryptographic algorithms can lead to inadequate encryption strength. (CWE-326)"
    }
}

# Detection in Attributes: weak algorithm in value
Glitch_Analysis[result] {
    parent := glitch_lib._gather_parent_unit_blocks[_]
    parent.path != ""

    atomic_units := glitch_lib.all_atomic_units(parent)
    unit := atomic_units[_]

    attrs := glitch_lib.all_attributes(unit)
    attr := attrs[_]

    is_crypto_attr_name(attr.name)
    node_contains_weak_algo(attr.value)

    result := {
        "type": "sec_weak_crypt",
        "element": attr,
        "path": parent.path,
        "description": "Use of weak cryptographic algorithm - Weak or deprecated cryptographic algorithms can lead to inadequate encryption strength. (CWE-326)"
    }
}

# Detection in Variables: weak algorithm in value
Glitch_Analysis[result] {
