    parent.path != ""

    vars := glitch_lib.all_variables(parent)
    var := vars[_]

    is_crypto_attr_name(var.name)
    node_contains_weak_algo(var.value)

    result := {
        "type": "sec_weak_crypt",
        "element": var,
        "path": parent.path,
        "description": "Use of weak cryptographic algorithm in variable - Weak or deprecated cryptographic algorithms can lead to inadequate encryption strength. (CWE-326)"
    }
}

# Detection: weak cipher suites in any string value
Glitch_Analysis[result] {
